head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.grid1_ongroupby = function(options) {
    return false;
};
scwin.dbClick = function(id) {
    var el = scwin.__getDom($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}

scwin.check = function() {
    return ((j) => j.length ? j : $('#G_mf_grid1__category3'))($('#G_grid1__category3')).position().top < 100 ? false : true;
}
scwin.checkVal2 = function() {
    return typeof (document.getElementById('G_grid1__category3') || document.getElementById('mf_G_grid1__category3') || document.getElementById('mf_G_mf_grid1__category3') || document.getElementById('G_mf_grid1__category3')) == 'object';
}

scwin.onpageload = function() {
    window.arr = [];
    for (window.i = 0; i < 50000; i++) {
        for (window.j = 0; j < 7; j++) {
            arr.push(Math.floor((Math.random() * (500 - 1 + 1)) + 1));
        }
    }
    /*
    window.arr = [];
    arr.push( 1 );
    arr.push( 2 );
    arr.push( 3 );
    arr.push( 4 );
    arr.push( 5 );
    arr.push( 6 );
    arr.push( 7 );
    arr.push( 8 );
    arr.push( 9 );
    arr.push( 10 );
    arr.push( 11 );
    arr.push( 12 );
    arr.push( 13 );
    arr.push( 14 );
    */
    dataList1.setData(arr);
    input1.setValue(" [ 0, 1, 2] ");
    input2.setValue(" [ 1, 0, 1] ");
    input3.setValue(" { inputType:'expression', expression: 'toggle()+depthStr()+\"    [ \"+count()+\" 건 ]\"', align: 'left', colSpan:9} ");
    input4.setValue("");
    input5.setValue("");
    input6.setValue(" {colSpan:7} ");
    input7.setValue(" {hidden:true} ");
    input8.setValue(' {"category1":["1","2","3"], "category2":["1","2","3"]} ');
    input9.setValue(" [ {value:'합계'}, {inputType:'expression', expression:'SUM(\"category7\")'} ] ");
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 13-Mar-2018
    //end
}

